export function classicPageSceneDetail(classicId:string,pageIndex:number):string{
 const story=storyChapters[classicId];
 if(!story)return "";
 const page=Math.max(0,Math.min(7,Math.trunc(Number.isFinite(pageIndex)?pageIndex:0)));
 const icon=story[page];
 const element=shapes[icon];
 if(!element)return "";
 const side=page%2===0?615:185;
 const y=page%3===0?425:page%3===1?360:465;
 const scale=.78+(page%3)*.08;
 return `<g data-story-page="${classicId}-${page+1}" aria-hidden="true" transform="translate(${side} ${y}) rotate(${(page%5-2)*7}) scale(${scale})" opacity=".92">${element}</g>`;
}
export const storyboardClassicIds=Object.freeze(Object.keys(storyChapters));
